query SearchPolicies($input: SearchInput!) {
  searchPolicies(input: $input) {
    pageInfo {
      hasNextPage
      endCursor
      startCursor
      __typename
    }
    edges {
      cursor
      node {
        id
        name
        type
        labels
        createdAt
        updatedAt
        body
        description
        plugin {
          id
          name
          __typename
        }
        spaceDetails {
          id
          name
          accessLevel
          __typename
        }
        hasAttachedStacks
        __typename
      }
      __typename
    }
    __typename
  }
}

