fragment SearchSuggestionsFragment on SearchSuggestionsOutput {
  filteredCount
  ...SearchSuggestionsFieldsFragment
  __typename
}

fragment SearchSuggestionsFieldsFragment on SearchSuggestionsOutput {
  fields {
    name
    orderable
    filterable
    type
    possibleValuesBoolean {
      values
      counts
      __typename
    }
    possibleValuesEnum {
      values
      counts
      __typename
    }
    possibleValuesString {
      values
      counts
      __typename
    }
    possibleValuesHierarchy {
      values {
        id
        parentId
        displayValue
        __typename
      }
      counts
      directCounts
      __typename
    }
    __typename
  }
  __typename
}

